void Z6BoardJson::from_json(const std::string& json_str) {
    json j = json::parse(json_str);
        if (j.contains("Active")) {
            active_ = j["Active"];
            active_valid_ = true;
        }
        if (j.contains("Turn")) {
            turn_ = j["Turn"];
            turn_valid_ = true;
        }
        if (j.contains("Nsides")) {
            nsides_ = j["Nsides"];
            nsides_valid_ = true;
        }
        if (j.contains("Nseeds")) {
            nseeds_ = j["Nseeds"];
            nseeds_valid_ = true;
        }
        if (j.contains("Npits")) {
            npits_ = j["Npits"];
            npits_valid_ = true;
        }
        if (j.contains("Pits")) {
            pits_.clear();
            for (const auto& item : j["Pits"]) {
                Z6PitJson obj;
                obj.from_json(item.dump());
                pits_.push_back(obj);
            }
            pits_valid_ = true;
        }
        if (j.contains("Nround")) {
            nround_ = j["Nround"];
            nround_valid_ = true;
        }
        if (j.contains("Visibility")) {
            visibility_ = j["Visibility"];
            visibility_valid_ = true;
        }
        if (j.contains("History")) {
            history_.clear();
            for (const auto& item : j["History"]) {
                Z6MoveHistoryJson obj;
                obj.from_json(item.dump());
                history_.push_back(obj);
            }
            history_valid_ = true;
        }
}

std::string Z6BoardJson::to_json() const {
    json j;
        if (active_valid_) {
            j["Active"] = active_;
        }
        if (turn_valid_) {
            j["Turn"] = turn_;
        }
        if (nsides_valid_) {
            j["Nsides"] = nsides_;
        }
        if (nseeds_valid_) {
            j["Nseeds"] = nseeds_;
        }
        if (npits_valid_) {
            j["Npits"] = npits_;
        }
        if (pits_valid_) {
            json arr = json::array();
            for (const auto& item : pits_) {
                arr.push_back(json::parse(item.to_json()));
            }
            j["Pits"] = arr;
        }
        if (nround_valid_) {
            j["Nround"] = nround_;
        }
        if (visibility_valid_) {
            j["Visibility"] = visibility_;
        }
        if (history_valid_) {
            json arr = json::array();
            for (const auto& item : history_) {
                arr.push_back(json::parse(item.to_json()));
            }
            j["History"] = arr;
        }
    return j.dump();
}

